<?php

namespace Database\Seeders;

use Database\Seeders\Concerns\LoadsTestProductionData;
use Database\Seeders\Support\TestProductionLinks;
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Schema;

/**
 * The master data of the test production dataset: products, shifts, pay grades, employees, work centres, sections,
 * machines, manual-production batches, staffing, external workers, calculations and activity logs.
 *
 * Runs after HrmsDemoSeeder and AddTestMastersSeeder (units, warehouses). Every reference to a row this data does not
 * own is a natural key — 'uom' => 'Pcs', 'warehouse' => 'WH-RM-TBL', 'shift' => 'DAY', 'employee' => 'WRG-002',
 * 'branch' => 'HQ', accounts by chart code — and is looked up in the database being seeded (see TestProductionLinks).
 * Rows this data owns keep their ids; the cleaner (CleanBeforeHrmsSeeder) has emptied those tables.
 *
 * Employees get the next free id and a production designation chosen from the job title. Opening stock is booked
 * by TestProductionExecutionSeeder, once it knows what the orders take out.
 */
class TestProductionMasterDataSeeder extends Seeder
{
    use LoadsTestProductionData;

    public function run(?int $tenantId = null): void
    {
        $tenantId = $this->resolveTenantId($tenantId);
        $links = new TestProductionLinks($tenantId);

        Schema::disableForeignKeyConstraints();

        try {
            foreach ($this->tables() as $table => $rows) {
                match ($table) {
                    'production_shifts' => $this->seedShifts($rows, $tenantId, $links),
                    'employees' => $this->seedEmployees($rows, $tenantId, $links),
                    default => $this->seedTable($table, $rows, $tenantId, $links),
                };
            }
        } finally {
            Schema::enableForeignKeyConstraints();
        }

        $this->command?->info("TestProductionMasterDataSeeder completed successfully for Tenant ID {$tenantId}.");
    }

    /**
     * Shifts get no fixed id: another tenant's shifts push the ids around. DAY, MRN, EVE and NGT come from HRMS and are
     * referenced by code; the shifts below are added once (a code that exists is left as it is).
     */
    private function seedShifts(array $rows, int $tenantId, TestProductionLinks $links): void
    {
        $columns = array_flip(Schema::getColumnListing('production_shifts'));

        foreach ($rows as $row) {
            if (DB::table('production_shifts')->where('tenant_id', $tenantId)->where('code', $row['code'])->exists()) {
                continue;
            }

            $row['tenant_id'] = $tenantId;
            DB::table('production_shifts')->insert(array_intersect_key($links->translate('production_shifts', $row), $columns));
        }
    }

    /** Employees are matched on their code (test-emp-N) and get the next free id, so they can never overwrite an HRMS employee. */
    private function seedEmployees(array $rows, int $tenantId, TestProductionLinks $links): void
    {
        $links->ensureDesignations($rows);
        $columns = array_flip(Schema::getColumnListing('employees'));

        foreach ($rows as $row) {
            $row['tenant_id'] = $tenantId;
            $row = array_intersect_key($links->translate('employees', $row), $columns);
            DB::table('employees')->updateOrInsert(['tenant_id' => $tenantId, 'employee_id' => $row['employee_id']], $row);
        }
    }

    /**
     * Everything the engineering and execution data stands on.
     *
     * @return array<string, array<int, array<string, mixed>>> table => rows, in the order they are loaded
     */
    public function tables(): array
    {
        return [
            'products' => $this->products(),
            'production_shifts' => $this->productionShifts(),
            'production_external_worker_pay_grades' => $this->productionExternalWorkerPayGrades(),
            'employees' => $this->employees(),
            'production_work_centers' => $this->productionWorkCenters(),
            'production_work_center_sections' => $this->productionWorkCenterSections(),
            'production_machines' => $this->productionMachines(),
            'production_section_manual_productions' => $this->productionSectionManualProductions(),
            'production_section_manual_production_employees' => $this->productionSectionManualProductionEmployees(),
            'production_work_center_employees' => $this->productionWorkCenterEmployees(),
            'production_external_worker_allocations' => $this->productionExternalWorkerAllocations(),
            'production_work_center_calculations' => $this->productionWorkCenterCalculations(),
            'production_work_center_section_calculations' => $this->productionWorkCenterSectionCalculations(),
            'production_work_center_activity_logs' => $this->productionWorkCenterActivityLogs(),
        ];
    }

